import Foundation
import AVFoundation
import CoreMedia
import VideoToolbox
import PhotoMatroska

// Headless acceptance for Matroska playback. Shared by `pv-pipeline` and the
// XCTest target; the fixtures are generated by scripts/make_matroska_fixtures.sh.

/// Every fixture builds a movie whose every video frame and audio packet
/// decodes, and whose first frame renders as a thumbnail.
public func verifyMatroskaFixturesDecode() async throws {
    var fixtures: [(name: String, frames: Int)] = [
        ("sync-aac", 90), ("sync-ac3", 90), ("sync-opus", 90), ("sync-mp3", 90),
        ("sync-flac", 90), ("sync-hevc-aac", 90), ("vp9-opus", 30),
    ]
    // AV1 decoding is hardware-only on Apple silicon (M3 and later).
    if VTIsHardwareDecodeSupported(kCMVideoCodecType_AV1) { fixtures.append(("av1-aac", 30)) }

    for fixture in fixtures {
        let url = try matroskaFixture(fixture.name)
        let movie = try await MatroskaMovie.open(url: url)
        try check(movie.skippedTracks.isEmpty, "\(fixture.name): skipped \(movie.skippedTracks.map(\.reason))")
        try check(movie.videoTrackCount == 1 && movie.audioTrackCount == 1,
                  "\(fixture.name): expected one video and one audio track")
        try check(movie.isComplete, "\(fixture.name): reported incomplete")
        let decoded = try await decodeAll(movie.asset)
        try check(decoded.videoFrames == fixture.frames,
                  "\(fixture.name): decoded \(decoded.videoFrames) of \(fixture.frames) video frames")
        try check(decoded.audioSeconds > Double(fixture.frames) / 30 - 0.05,
                  "\(fixture.name): only \(decoded.audioSeconds)s of audio decoded")

        let generator = AVAssetImageGenerator(asset: movie.asset)
        let image = try await generator.image(at: .zero).image
        try check(image.width > 0 && image.height > 0, "\(fixture.name): empty thumbnail")
    }
}

/// Each sync fixture flashes white on the video frame at 1.000 s and clicks
/// at 1.000 s in its audio. Every audio codec arrives through a different
/// combination of encoder priming, Matroska CodecDelay and what AVFoundation
/// trims on its own (see `AudioStart`); all of them must land together.
public func verifyMatroskaAudioSync() async throws {
    for name in ["sync-aac", "sync-ac3", "sync-opus", "sync-mp3", "sync-flac", "sync-hevc-aac"] {
        let movie = try await MatroskaMovie.open(url: try matroskaFixture(name))
        let (flash, click) = try await flashAndClick(movie.asset)
        try check(abs(flash - 1) < 0.001, "\(name): flash decoded at \(flash)s instead of 1.000s")
        let offset = (click - flash) * 1000
        try check(abs(offset) < 2, "\(name): audio is \(String(format: "%+.1f", offset)) ms off the video")
    }
}

/// A synthetic file exercising what ffmpeg never writes: Xiph, EBML and
/// fixed lacing, a BlockGroup with BlockDuration, an unknown-size Segment
/// and Cluster (a recording still being written), a file cut off mid-block,
/// and tracks macOS cannot decode. The PCM payload is a running sample
/// counter, so any frame placed at the wrong offset or time shows up as a
/// break in the decoded ramp.
public func verifyMatroskaLacingAndDamage() async throws {
    let file = SyntheticMatroska.lacedPCM()
    let url = try writeTemporary(file.data, name: "laced.mkv")
    defer { try? FileManager.default.removeItem(at: url) }

    let index = try MatroskaIndex.read(url: url)
    try check(!index.isComplete, "a file cut off mid-block must read as incomplete")
    guard let pcm = index.tracks.first(where: { $0.number == 1 }) else { throw failure("PCM track missing") }
    try check(pcm.frames.map(\.offset) == file.frameOffsets,
              "frame offsets \(pcm.frames.map(\.offset)) != \(file.frameOffsets)")
    try check(pcm.frames.map { Int($0.size) } == file.frameSizes,
              "frame sizes \(pcm.frames.map(\.size)) != \(file.frameSizes)")
    try check(pcm.frames.map(\.timestamp) == file.frameTimestamps,
              "frame timestamps \(pcm.frames.map(\.timestamp)) != \(file.frameTimestamps)")

    let movie = try MatroskaMovie.load(url: url)
    try check(movie.audioTrackCount == 1 && movie.videoTrackCount == 0, "only the PCM track should play")
    let reasons = movie.skippedTracks.map(\.reason).joined(separator: "; ")
    try check(reasons.contains("DTS") && reasons.contains("VP8"), "skip reasons should name DTS and VP8: \(reasons)")
    let samples = try await decodePCM16(movie.asset)
    try check(samples.count == file.sampleCount, "decoded \(samples.count) of \(file.sampleCount) samples")
    if let broken = samples.indices.first(where: { samples[$0] != Int16(truncatingIfNeeded: $0) }) {
        throw failure("decoded ramp breaks at sample \(broken): \(samples[broken])")
    }

    // A thumbnail read stops at the first Cluster past the limit.
    let partial = try MatroskaIndex.read(url: url, limit: 0.25)
    try check(!partial.isComplete, "a limited read must report incomplete")
    try check(partial.tracks.first { $0.number == 1 }?.frames.count == file.framesBeforeSecondCluster,
              "a 0.25 s limit should stop before the second cluster")
}

/// Files that are not playable fail with a reason a viewer can show,
/// instead of a crash or a silent empty player.
public func verifyMatroskaRejectsUnplayableFiles() async throws {
    let cases: [(String, Data, (MatroskaError) -> Bool)] = [
        ("empty file", Data(), { $0 == .notMatroska }),
        ("PNG bytes", Data([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, 0, 0, 0, 13]), { $0 == .notMatroska }),
        ("unknown DocType", SyntheticMatroska.header(docType: "notmatroska"), { $0 == .unsupportedDocType("notmatroska") }),
        ("header without a Segment", SyntheticMatroska.header(docType: "matroska"), { $0 == .noSegment }),
        ("only a DTS track", SyntheticMatroska.dtsOnly(), {
            if case .noPlayableTracks(let reasons) = $0 { return reasons.contains { $0.contains("DTS") } }
            return false
        }),
    ]
    for (label, data, expected) in cases {
        let url = try writeTemporary(data, name: "reject.mkv")
        defer { try? FileManager.default.removeItem(at: url) }
        do {
            _ = try MatroskaMovie.load(url: url)
            throw failure("\(label): loaded instead of failing")
        } catch let error as MatroskaError {
            try check(expected(error), "\(label): unexpected error \(error)")
            try check(!error.description.isEmpty, "\(label): error has no description")
        }
    }

    do {
        _ = try MatroskaMovie.load(url: URL(fileURLWithPath: "/nonexistent/\(UUID().uuidString).mkv"))
        throw failure("a missing file loaded")
    } catch MatroskaError.unreadable {
        // expected
    }
}

// MARK: - Helpers

private struct VerificationFailure: Error, CustomStringConvertible {
    let description: String
}

private func failure(_ message: String) -> VerificationFailure {
    VerificationFailure(description: message)
}

private func check(_ condition: Bool, _ message: @autoclosure () -> String) throws {
    if !condition { throw failure(message()) }
}

private func matroskaFixture(_ name: String) throws -> URL {
    guard let url = Bundle.module.url(forResource: name, withExtension: "mkv", subdirectory: "Matroska") else {
        throw failure("missing fixture \(name).mkv")
    }
    return url
}

private func writeTemporary(_ data: Data, name: String) throws -> URL {
    let url = FileManager.default.temporaryDirectory
        .appendingPathComponent("latent-matroska-\(UUID().uuidString)-\(name)")
    try data.write(to: url)
    return url
}

private func decodeAll(_ asset: AVAsset) async throws -> (videoFrames: Int, audioSeconds: Double) {
    let reader = try AVAssetReader(asset: asset)
    let video = try await asset.loadTracks(withMediaType: .video).first.map {
        AVAssetReaderTrackOutput(track: $0, outputSettings: [
            kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA,
        ])
    }
    let audio = try await asset.loadTracks(withMediaType: .audio).first.map {
        AVAssetReaderTrackOutput(track: $0, outputSettings: [AVFormatIDKey: kAudioFormatLinearPCM])
    }
    if let video { reader.add(video) }
    if let audio { reader.add(audio) }
    guard reader.startReading() else { throw failure("reader failed to start: \(String(describing: reader.error))") }
    var frames = 0
    while let sample = video?.copyNextSampleBuffer() {
        if CMSampleBufferGetImageBuffer(sample) != nil { frames += 1 }
    }
    var seconds = 0.0
    while let sample = audio?.copyNextSampleBuffer() {
        seconds += CMSampleBufferGetDuration(sample).seconds
    }
    try check(reader.status == .completed, "decoding stopped: \(String(describing: reader.error))")
    return (frames, seconds)
}

/// Presentation time of the first bright video frame and of the first loud
/// audio sample.
private func flashAndClick(_ asset: AVAsset) async throws -> (flash: Double, click: Double) {
    let reader = try AVAssetReader(asset: asset)
    guard let videoTrack = try await asset.loadTracks(withMediaType: .video).first,
          let audioTrack = try await asset.loadTracks(withMediaType: .audio).first else {
        throw failure("sync fixture needs video and audio")
    }
    let video = AVAssetReaderTrackOutput(track: videoTrack, outputSettings: [
        kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA,
    ])
    let audio = AVAssetReaderTrackOutput(track: audioTrack, outputSettings: [
        AVFormatIDKey: kAudioFormatLinearPCM, AVLinearPCMIsFloatKey: true, AVLinearPCMBitDepthKey: 32,
        AVLinearPCMIsNonInterleaved: false, AVNumberOfChannelsKey: 1,
    ])
    reader.add(video)
    reader.add(audio)
    guard reader.startReading() else { throw failure("reader failed to start: \(String(describing: reader.error))") }

    var flash = Double.nan
    while let sample = video.copyNextSampleBuffer() {
        guard flash.isNaN, let pixels = CMSampleBufferGetImageBuffer(sample) else { continue }
        CVPixelBufferLockBaseAddress(pixels, .readOnly)
        let base = CVPixelBufferGetBaseAddress(pixels)!.assumingMemoryBound(to: UInt8.self)
        let middle = CVPixelBufferGetBytesPerRow(pixels) * (CVPixelBufferGetHeight(pixels) / 2) + 40
        let bright = base[middle] > 128
        CVPixelBufferUnlockBaseAddress(pixels, .readOnly)
        if bright { flash = CMSampleBufferGetPresentationTimeStamp(sample).seconds }
    }

    var click = Double.nan
    while let sample = audio.copyNextSampleBuffer() {
        guard click.isNaN, let format = CMSampleBufferGetFormatDescription(sample),
              let rate = CMAudioFormatDescriptionGetStreamBasicDescription(format)?.pointee.mSampleRate else { continue }
        let start = CMSampleBufferGetPresentationTimeStamp(sample).seconds
        let values = floatSamples(sample)
        if let loud = values.firstIndex(where: { abs($0) > 0.3 }) {
            click = start + Double(loud) / rate
        }
    }
    try check(!flash.isNaN, "no flash found in the video")
    try check(!click.isNaN, "no click found in the audio")
    return (flash, click)
}

private func floatSamples(_ sample: CMSampleBuffer) -> [Float] {
    guard let block = CMSampleBufferGetDataBuffer(sample) else { return [] }
    let length = CMBlockBufferGetDataLength(block)
    var values = [Float](repeating: 0, count: length / MemoryLayout<Float>.size)
    values.withUnsafeMutableBytes { raw in
        _ = CMBlockBufferCopyDataBytes(block, atOffset: 0, dataLength: raw.count, destination: raw.baseAddress!)
    }
    return values
}

private func decodePCM16(_ asset: AVAsset) async throws -> [Int16] {
    guard let track = try await asset.loadTracks(withMediaType: .audio).first else { throw failure("no audio track") }
    let reader = try AVAssetReader(asset: asset)
    let output = AVAssetReaderTrackOutput(track: track, outputSettings: [
        AVFormatIDKey: kAudioFormatLinearPCM, AVLinearPCMBitDepthKey: 16, AVLinearPCMIsFloatKey: false,
        AVLinearPCMIsBigEndianKey: false, AVLinearPCMIsNonInterleaved: false,
    ])
    reader.add(output)
    guard reader.startReading() else { throw failure("reader failed to start: \(String(describing: reader.error))") }
    var samples: [Int16] = []
    while let sample = output.copyNextSampleBuffer() {
        guard let block = CMSampleBufferGetDataBuffer(sample) else { continue }
        let length = CMBlockBufferGetDataLength(block)
        var chunk = [Int16](repeating: 0, count: length / 2)
        chunk.withUnsafeMutableBytes { raw in
            _ = CMBlockBufferCopyDataBytes(block, atOffset: 0, dataLength: raw.count, destination: raw.baseAddress!)
        }
        samples += chunk
    }
    try check(reader.status == .completed, "decoding stopped: \(String(describing: reader.error))")
    return samples
}

// MARK: - Synthetic files

/// Writes small Matroska files byte by byte, recording where every frame
/// lands so the index can be checked exactly.
private enum SyntheticMatroska {
    struct Laced {
        var data: Data
        var frameOffsets: [Int64]
        var frameSizes: [Int]
        var frameTimestamps: [Int64]
        var sampleCount: Int
        var framesBeforeSecondCluster: Int
    }

    static func header(docType: String) -> Data {
        // EBMLVersion, EBMLReadVersion, EBMLMaxIDLength, EBMLMaxSizeLength,
        // DocType, DocTypeVersion, DocTypeReadVersion.
        element(0x1A45DFA3, uint(0x4286, 1) + uint(0x42F7, 1) + uint(0x42F2, 4) + uint(0x42F3, 8)
                + string(0x4282, docType) + uint(0x4287, 4) + uint(0x4285, 2))
    }

    /// 8 kHz mono 16-bit PCM whose samples count up from zero, in blocks
    /// that use every lacing mode; plus a DTS and a VP8 track to skip.
    static func lacedPCM() -> Laced {
        var out = header(docType: "matroska")
        // Unknown-size Segment, as a live recorder writes it.
        out += id(0x18538067) + Data([0x01, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF])
        out += element(0x1549A966, uint(0x2AD7B1, 1_000_000))
        let pcm = element(0xAE, uint(0xD7, 1) + uint(0x83, 2) + string(0x86, "A_PCM/INT/LIT")
                          + element(0xE1, float(0xB5, 8000) + uint(0x9F, 1) + uint(0x6264, 16)))
        let dts = element(0xAE, uint(0xD7, 2) + uint(0x83, 2) + string(0x86, "A_DTS")
                          + element(0xE1, float(0xB5, 48000) + uint(0x9F, 2)))
        let vp8 = element(0xAE, uint(0xD7, 3) + uint(0x83, 1) + string(0x86, "V_VP8")
                          + element(0xE0, uint(0xB0, 64) + uint(0xBA, 64)))
        out += element(0x1654AE6B, pcm + dts + vp8)

        var next = 0
        func frames(_ counts: [Int]) -> [Data] {
            counts.map { count in
                var bytes = Data(capacity: count * 2)
                for _ in 0..<count {
                    let value = UInt16(truncatingIfNeeded: next)
                    bytes.append(UInt8(value & 0xFF))
                    bytes.append(UInt8(value >> 8))
                    next += 1
                }
                return bytes
            }
        }

        var offsets: [Int64] = []
        var sizes: [Int] = []
        var timestamps: [Int64] = []

        // Appends a block element whose frames start after `prelude` bytes
        // of block header, recording where each frame sits in the file.
        func appendBlock(to cluster: inout Data, clusterDataStart: Int, elementID: UInt32,
                         prelude: Data, payloads: [Data], timestamp: Int64, wrap: ((Data) -> Data)? = nil) {
            let body = prelude + payloads.reduce(Data(), +)
            let block = element(elementID, body)
            let wrapped = wrap?(block) ?? block
            // The block element is the last thing inside `wrapped`.
            let blockStart = clusterDataStart + cluster.count + (wrapped.count - block.count)
            var frameStart = blockStart + (block.count - body.count) + prelude.count
            for payload in payloads {
                offsets.append(Int64(frameStart))
                sizes.append(payload.count)
                timestamps.append(timestamp)
                frameStart += payload.count
            }
            cluster += wrapped
        }

        // Cluster 1, known size: Xiph, EBML and fixed lacing, then a BlockGroup.
        let clusterHeaderLength = 4 + 8
        var first = uint(0xE7, 0)
        let firstStart = out.count + clusterHeaderLength
        let xiph = frames([300, 260, 520])
        appendBlock(to: &first, clusterDataStart: firstStart, elementID: 0xA3,
                    prelude: blockHeader(track: 1, time: 0, flags: 0x80 | 0x02)
                        + Data([2]) + xiphSize(xiph[0].count) + xiphSize(xiph[1].count),
                    payloads: xiph, timestamp: 0)
        let ebml = frames([200, 230, 180])
        appendBlock(to: &first, clusterDataStart: firstStart, elementID: 0xA3,
                    prelude: blockHeader(track: 1, time: 135, flags: 0x80 | 0x06)
                        + Data([2]) + Data([0x40 | UInt8(ebml[0].count >> 8), UInt8(ebml[0].count & 0xFF)])
                        + signedVint(ebml[1].count - ebml[0].count),
                    payloads: ebml, timestamp: 135)
        let fixed = frames([100, 100, 100, 100])
        appendBlock(to: &first, clusterDataStart: firstStart, elementID: 0xA3,
                    prelude: blockHeader(track: 1, time: 211, flags: 0x80 | 0x04) + Data([3]),
                    payloads: fixed, timestamp: 211)
        let grouped = frames([200])
        appendBlock(to: &first, clusterDataStart: firstStart, elementID: 0xA1,
                    prelude: blockHeader(track: 1, time: 261, flags: 0), payloads: grouped, timestamp: 261,
                    wrap: { block in
                        // BlockDuration first, so the Block ends the group.
                        let inner = uint(0x9B, 25) + block
                        return id(0xA0) + size(inner.count) + inner
                    })
        // A DTS frame and a VP8 frame the movie must skip, not choke on.
        first += element(0xA3, blockHeader(track: 2, time: 0, flags: 0x80) + Data(repeating: 0x7F, count: 16))
        first += element(0xA3, blockHeader(track: 3, time: 0, flags: 0x80) + Data(repeating: 0x9D, count: 16))
        out += id(0x1F43B675) + size(first.count) + first
        let framesBeforeSecondCluster = offsets.count

        // Cluster 2, unknown size: ends where the next Cluster begins.
        var second = uint(0xE7, 286)
        let secondStart = out.count + clusterHeaderLength
        appendBlock(to: &second, clusterDataStart: secondStart, elementID: 0xA3,
                    prelude: blockHeader(track: 1, time: 0, flags: 0x80), payloads: frames([200]), timestamp: 286)
        out += id(0x1F43B675) + Data([0x01, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF]) + second

        // Cluster 3, cut off partway through its second block.
        var third = uint(0xE7, 311)
        let thirdStart = out.count + clusterHeaderLength
        appendBlock(to: &third, clusterDataStart: thirdStart, elementID: 0xA3,
                    prelude: blockHeader(track: 1, time: 0, flags: 0x80), payloads: frames([200]), timestamp: 311)
        let sampleCount = next
        let torn = element(0xA3, blockHeader(track: 1, time: 25, flags: 0x80) + frames([200])[0])
        third += torn
        out += id(0x1F43B675) + size(third.count) + third
        out.removeLast(torn.count / 2)

        return Laced(data: out, frameOffsets: offsets, frameSizes: sizes, frameTimestamps: timestamps,
                     sampleCount: sampleCount, framesBeforeSecondCluster: framesBeforeSecondCluster)
    }

    static func dtsOnly() -> Data {
        var out = header(docType: "matroska")
        let dts = element(0xAE, uint(0xD7, 1) + uint(0x83, 2) + string(0x86, "A_DTS")
                          + element(0xE1, float(0xB5, 48000) + uint(0x9F, 2)))
        let cluster = element(0x1F43B675, uint(0xE7, 0)
                              + element(0xA3, blockHeader(track: 1, time: 0, flags: 0x80) + Data(repeating: 0x7F, count: 16)))
        out += element(0x18538067, element(0x1549A966, uint(0x2AD7B1, 1_000_000)) + element(0x1654AE6B, dts) + cluster)
        return out
    }

    // MARK: EBML encoding

    static func id(_ value: UInt32) -> Data {
        let length = value > 0xFFFFFF ? 4 : value > 0xFFFF ? 3 : value > 0xFF ? 2 : 1
        return Data((0..<length).reversed().map { UInt8(truncatingIfNeeded: value >> (8 * UInt32($0))) })
    }

    /// Eight-byte size: always valid, never ambiguous with "unknown".
    static func size(_ value: Int) -> Data {
        Data([0x01] + (0..<7).reversed().map { UInt8(truncatingIfNeeded: UInt64(value) >> (8 * UInt64($0))) })
    }

    static func element(_ elementID: UInt32, _ body: Data) -> Data {
        id(elementID) + size(body.count) + body
    }

    static func uint(_ elementID: UInt32, _ value: UInt64) -> Data {
        element(elementID, Data((0..<8).reversed().map { UInt8(truncatingIfNeeded: value >> (8 * UInt64($0))) }))
    }

    static func float(_ elementID: UInt32, _ value: Double) -> Data {
        let bits = value.bitPattern
        return element(elementID, Data((0..<8).reversed().map { UInt8(truncatingIfNeeded: bits >> (8 * UInt64($0))) }))
    }

    static func string(_ elementID: UInt32, _ value: String) -> Data {
        element(elementID, Data(value.utf8))
    }

    static func blockHeader(track: UInt8, time: Int16, flags: UInt8) -> Data {
        let t = UInt16(bitPattern: time)
        return Data([0x80 | track, UInt8(t >> 8), UInt8(t & 0xFF), flags])
    }

    static func xiphSize(_ value: Int) -> Data {
        Data(repeating: 0xFF, count: value / 255) + Data([UInt8(value % 255)])
    }

    /// EBML lacing's signed size difference, two bytes wide (bias 8191).
    static func signedVint(_ difference: Int) -> Data {
        let raw = difference + 8191
        return Data([0x40 | UInt8(raw >> 8), UInt8(raw & 0xFF)])
    }
}
